
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_tau_hcth_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_tau_hcth", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-7.490990799254121e-02, -7.579344276032539e-02, -7.709612168451771e-02, -7.902592182708221e-02, -8.188708381422714e-02, -8.608222941377132e-02, -9.197048189376236e-02, -9.913009292441527e-02, -1.035130463355562e-01, -9.060924844800437e-02, -5.276478133374721e-02, -4.943406621218237e-02, -2.849312013557827e-02, -4.435824431193647e-02, -4.229341190673647e-02, 5.986520003374403e-03, 3.546186454888018e-02, 8.977857176730280e-03, -8.710403246382770e-04, -3.416717568700340e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


